mapper.select:
SELECT /* homes.stuff.mapper.StuffMapper.selectRelatedJibunCount 관련지번 포함여부 */
       COUNT(SHTBDNO) AS HAS_RELJIBUN
FROM   TB_HBD_LEDGR_MSTR_RELJIBUN A

WHERE  SHTBDNO = #{htbdno}


WHERE  ARCD = #{arcd}
AND    LEGCD = #{legcd}
AND    BUNJIB = #{bun}

SELECT /* homes.stuff.mapper.StuffMapper.selectBuldGroup 집합건물 정보 조회 */ A.GBULDNO, A.BULDNO, A.BULD_REGSTR_PK , A.BDADDR, A.BULDNM , A.ARCD, A.LEGCD , A.BUNJIB AS BUN , A.BUNJIJ AS JI , A.BULDCO, A.HSHLDCO, A.FMLYCO , B.MAIN_PPS_CD AS PPSCD , B.ETC_PPS , E.AR_FULL_NM AS ARNAME FROM TB_HBD_BULD_GROUP A INNER JOIN TB_BD_TITLE_LEDGR_PPS B ON A.BULD_REGSTR_PK = B.BULD_REGSTR_PK INNER JOIN TB_CM_COAREACODE E ON A.ARCD = E.ARCODE AND A.LEGCD = E.LEGCODE WHERE A.ARCD = #{arcd} AND A.LEGCD = #{legcd} AND A.BUNJIB = #{bun} AND A.BUNJIJ = #{ji}
AND A.BULDNM = #{buldnm}
AND E.USE_YN = 'Y' AND E.ARLEVEL = 3

SELECT /* homes.stuff.mapper.StuffMapper.isBuldGroup 집합건물인지 확인한다. */
       CASE WHEN COUNT(1)  >  0 THEN 'Y' ELSE 'N' END AS CNDO_YN
FROM   TB_HBD_BULD_GROUP A
WHERE  A.ARCD = #{arcd} 
AND    A.LEGCD = #{legcd}
AND    A.BUNJIB = #{bun}
AND    A.BUNJIJ = #{ji} 

AND    A.BULDNM = #{buldnm}

SELECT /* homes.stuff.mapper.StuffMapper.selectPostcodeBuld 다음주소검색을통한 건물조회 */ A.BULD_REGSTR_PK AS BULDNO , A.PLOT_LOC AS PLOT_LOC , A.BULD_NM AS BULDNM , A.ARCD AS ARCD , A.LEGCD AS LEGCD , A.BUN AS BUN , A.JI AS JI , E.AR_FULL_NM AS ARNAME , B.MAIN_PPS_CD AS PPS_CD , DATE_FORMAT(D.PRMISS_DE, '%Y.%m.%d') AS PRMISS_DE , SUBSTR(D.PRMISS_DE, 1, 4) AS PRMISS_YY , SUBSTR(D.PRMISS_DE, 5, 2) AS PRMISS_MM , SUBSTR(D.PRMISS_DE, 7, 2) AS PRMISS_DD , #{naverx} AS NAVERX /* 네이버 기준 (위도) */ , #{navery} AS NAVERY /* 네이버 기준 (경도) */ , #{kakaox} AS KAKAOX /* 카카오 기준 (경도) */ , #{kakaoy} AS KAKAOY /* 카카오 기준 (위도) */ FROM TB_BD_TITLE_LEDGR A INNER JOIN TB_BD_TITLE_LEDGR_PPS B ON A.BULD_REGSTR_PK = B.BULD_REGSTR_PK INNER JOIN TB_BD_TITLE_LEDGR_PRMISS_DE D ON A.BULD_REGSTR_PK = D.BULD_REGSTR_PK INNER JOIN TB_CM_COAREACODE E ON ( A.ARCD = E.ARCODE AND A.LEGCD = E.LEGCODE ) WHERE A.ARCD = #{arcd} AND A.LEGCD = #{legcd} AND A.BUN = #{bun} AND A.JI = #{ji} AND E.USE_YN = 'Y' AND E.ARLEVEL = 3
AND A.BULD_NM = #{buldnm}
LIMIT 1

SELECT /* homes.stuff.mapper.StuffMapper.isExistsStuff 물건등록여부 확인 */
       CASE WHEN COUNT(1)  >  0 THEN 'Y' ELSE 'N' END AS IS_STUFF
FROM   TB_HBD_BULD_STUFF
WHERE  BULDNO = #{buldno}

AND    PSSIONNO = #{pssionno}

SELECT /* homes.stuff.mapper.StuffMapper.selectHbdLedgr 통합DB(표제부) 등록정보 확인 */ A.HBDNO AS HBDNO , A.HTBDNO AS HTBDNO , A.BULD_REGSTR_PK AS BREGSTR_PK , A.BULDGB AS BULDGB , A.BDADDR AS BDADDR , A.RDADDR AS RDADDR , A.PPSCD AS PPSCD , A.PPSETCNM AS PPSETCNM , A.ESTCD AS ESTCD , A.CFMVGB AS CFMVGB , A.CONFDE AS CONFDE , A.MOVEINDE AS MOVEINDE , A.BULDNM AS BULDNM , A.DONGNM AS DONGNM , A.RIDNG_ELVTR_CO AS RIDE_ELVTRCO , A.GRNDCO AS GRNDCO , A.UNDERCO AS UNDERCO FROM TB_HBD_LEDGR A WHERE A.BULDGB = #{buldgb}
AND A.HTBDNO IN ( SELECT C.SHTBDNO FROM TB_HBD_LEDGR_MSTR_RELJIBUN C INNER JOIN TB_HBD_LEDGR_MSTR_RELJIBUN D ON C.MHTBDNO = D.MHTBDNO WHERE D.SHTBDNO = #{htbdno} )
AND A.HTBDNO = #{htbdno}
ORDER BY A.DONGNM ASC

SELECT /* homes.stuff.mapper.StuffMapper.selectTitleLedgrinfo 통합DB(표제부) 등록정보 확인 */
       A.BULD_REGSTR_PK AS LEDGRNO
       , A.REGSTR_GB_CD AS BULD_TY
       , A.PLOT_LOC     AS BDADDR
       , A.ARCD         AS ARCD
       , A.LEGCD        AS LEGCD
       , A.BUN          AS BUNJIB
       , A.JI           AS BUNJIJ
FROM   TB_BD_TITLE_LEDGR A
WHERE  A.ARCD = #{arcd}
AND    A.LEGCD = #{legcd}
AND    A.BUN = #{bun}
AND    A.JI = #{ji}

AND    A.BULD_NM = #{buldnm}

LIMIT  1

SELECT /* homes.stuff.mapper.StuffMapper.selectHomesBuldinfo 홈즈DB(개별DB) 등록정보 확인 */ A.BULDNO AS BULDNO , A.BULD_REGSTR_PK AS LEDGRNO , A.BULD_TY AS BULD_TY , A.BULD_CD AS BULDCD , A.BDADDR AS BDADDR , A.RDADDR AS RDADDR , A.BULDNM AS BULDNM , A.BLOCKNM AS BLOCKNM , A.HSHLDCO AS HSHLDCO , A.FMLYCO AS FMLYCO , A.DISP_YN AS DISP_YN , A.ARCD AS ARCD , A.LEGCD AS LEGCD , A.BUNJIB AS BUNJIB , A.BUNJIJ AS BUNJIJ FROM TB_HBD_BULD A WHERE A.ARCD = #{arcd} AND A.LEGCD = #{legcd} AND A.BUNJIB = #{bun} AND A.BUNJIJ = #{ji}
AND A.BULDNM = #{buldnm}
LIMIT 1

SELECT /* homes.stuff.mapper.StuffMapper.getStuffno 물건번호조회 */
       STUFFNO
FROM   TB_HBD_BULD_STUFF 
WHERE  BULDNO = #{buldno}

AND    PSSIONNO = #{pssionno}

LIMIT  1

SELECT /* homes.stuff.mapper.StuffMapper.isExistsOwner 소유주 존재여부 확인 */
       NVL(MAX(OWNO), '000') AS OWNO
       , COUNT(1)            AS OWSEQ 
FROM   TB_BRK_BULD_OWNER
WHERE  BRKNO = #{brkno}
AND    STUFFNO = #{stuffno}

		SELECT /* homes.stuff.mapper.StuffMapper.getHtbdno HTBDNO 채번 */
               CONCAT('HTB', LPAD(#{buldgb}, 2, '0'), #{arcd}, #{legcd}
                           , LPAD(NVL(MAX(SUBSTR(A.HTBDNO, 15)), 0) + 1, 7, '0')) AS HTBDNO
		FROM   TB_HBD_BASE_SUMMRY A
		WHERE  BULDGB = #{buldgb}
		AND    ARCD = #{arcd}
		AND    LEGCD = #{legcd}

SELECT /* homes.stuff.mapper.StuffMapper.getBuldno BULDNO 채번 */
       CONCAT('HBD', LPAD(COUNT(1) + 1, 30, '0')) AS BULDNO
FROM   TB_HBD_LEDGR
WHERE  ARCD = #{arcd}
AND    LEGCD = #{legcd}
AND    BUNJIB = #{bun}
AND    BUNJIJ = #{ji}

SELECT /* homes.stuff.mapper.StuffMapper.getHbdTitleLedgrCount 표제부 등록여부 확인 */
       COUNT(1) AS CNT 
FROM   TB_HBD_TITLE_LEDGR 
WHERE  ARCD = #{arcd}
AND    LEGCD = #{legcd}
AND    BUNJIB = #{bun}
AND    BUNJIJ = #{ji}

SELECT /* homes.stuff.mapper.StuffMapper.selectRelatedbunji 관련지번 조회 */ 
       ARCODE
       , CONCAT(ARNAME_1, ' ', ARNAME_2, ' ', ARNAME_3, ' ', NVL(ARNAME_4, ''), ' ') AS ARNAME
       , BUNJIB      AS BUNJIB
       , BUNJIJ      AS BUNJIJ
       , RDCODE      AS RDCODE
       , RD_MAIN_BUN AS RD_MAIN_BUN 
FROM   TB_RD_RDRELATE_JIBUN
WHERE  ARCODE = #{arcode}
AND    BUNJIB = #{bun}
AND    RDCODE = #{rdcode}
AND    RD_MAIN_BUN = #{rdmainb}

SELECT /* homes.stuff.mapper.StuffMapper.getLedgrCount 홈즈_관리대장_표제부 카운트 */
       COUNT(1) AS LEDGR_CNT
FROM   TB_HBD_LEDGR 
WHERE  ARCD = #{arcd}
AND    LEGCD = #{legcd} 
AND    BUNJIB = #{bun}

AND    BUNJIJ = #{ji}


AND    USE_YN = #{useYn}

mapper.insert:
INSERT INTO /* homes.stuff.mapper.StuffMapper.insertHbdStuff 물건등록 */ 
TB_HBD_BULD_STUFF (
	STUFFNO, BULDNO, CPLXNO, PSSIONNO, CREAT_USER_NO, UPDT_USER_NO  
) VALUES (
	#{stuffno}
	, #{buldno}
	, #{cplxno}
	, #{pssionno}
	, #{brkno}
	, #{brkno}
)

INSERT INTO /* homes.stuff.mapper.StuffMapper.insertBrkStuff 중개사 물건등록 */ 
TB_BRK_BULD_STUFF (
	BRKNO, STUFFNO, SFSTTUS, CREAT_USER_NO, UPDT_USER_NO
) VALUES (
	#{brkno}
	, #{stuffno}
	, #{sfsttus}
	, #{brkno}
	, #{brkno}
)

INSERT /* homes.stuff.mapper.StuffMapper.insertBrkOwner 소유주 등록 */
INTO   TB_BRK_BULD_OWNER (
	OWNO, OWSEQ, BRKNO, USERNO, STUFFNO, STFFNM01, STFFNM02
	, OWNER_TY, OWNERNM, CCB_CD, CTTPC, OWSTTUS
	, CREAT_USER_NO, UPDT_USER_NO
) VALUES (
	#{owno}
	, #{owseq}
	, #{brkno}
	, #{userno}
	, #{stuffno}
	, #{stffnm01}
	, #{stffnm02}
	, #{ownerTy}
	, #{ownernm}
	, #{ccbCd}
	, #{cttpc}
	, #{owsttus}
	, #{brkno}
	, #{brkno}
)

mapper.delete:
DELETE /* homes.stuff.mapper.StuffMapper.deleteBrkStuff 중개사 물건삭제 */
FROM   TB_BRK_BULD_STUFF
WHERE  BRKNO = #{brkno}
AND    STUFFNO = #{stuffno}

mapper.update:
UPDATE /* homes.stuff.mapper.StuffMapper.deleteBrkStuff 중개사 물건 상태변경 */
TB_BRK_BULD_STUFF
SET    SFSTTUS = #{sfsttus}
WHERE  BRKNO = #{brkno}
AND    STUFFNO = #{stuffno}

UPDATE /* homes.stuff.mapper.StuffMapper.updateBrkOwner 소유주 수정 */
TB_BRK_BULD_OWNER
SET    UPDT_USER_NO = #{brkno}
       , UPDT_DT = NOW()

       , USERNO = #{userno}


       , CNTC_PERSN_YN = #{cntcpersnYn}

       , OWNER_TY = #{ownerTy}
       , OWNERNM = #{ownernm}
       , CCB_CD = #{ccbCd}
       , CTTPC = #{cttpc}
       , STFFNM01 = #{stffnm01}
       , STFFNM02 = #{stffnm02}
WHERE  OWNO = #{owno}
AND    OWSEQ = #{owseq}
AND    BRKNO = #{brkno}
